args.command:
node -e '
const { execSync } = require("child_process");

const resources = ["deployments", "statefulsets", "daemonsets", "cronjobs", "configmaps", "services", "networkpolicies", "pods"];

for (const res of resources) {
  const jsonStr = execSync(`kubectl get ${res} -A -o json`).toString();
  const list = JSON.parse(jsonStr);
  for (const item of list.items) {
    const ns = item.metadata.namespace || "cluster";
    const name = item.metadata.name;
    const ann = item.metadata.annotations || {};
    const lastApplied = ann["kubectl.kubernetes.io/last-applied-configuration"];
    if (lastApplied) {
      try {
        const orig = JSON.parse(lastApplied);
        // Compare spec or data
        const origSpec = JSON.stringify(orig.spec || orig.data || {});
        const currSpec = JSON.stringify(item.spec || item.data || {});
        if (origSpec !== currSpec) {
          console.log(`[DIFF] ${res} ${ns}/${name}`);
          console.log("  ORIG:", origSpec);
          console.log("  CURR:", currSpec);
        }
      } catch (e) {
        console.error("Error parsing lastApplied for", ns, name, e.message);
      }
    }
  }
}
'

