args.command:
node -e '
const { execSync } = require("child_process");

function checkDiff(kind) {
  const data = JSON.parse(execSync(`kubectl get ${kind} -A -o json`).toString());
  for (const item of data.items) {
    const ns = item.metadata.namespace || "cluster";
    const name = item.metadata.name;
    const ann = item.metadata.annotations || {};
    const lastApplied = ann["kubectl.kubernetes.io/last-applied-configuration"];
    if (lastApplied) {
      const orig = JSON.parse(lastApplied);
      if (kind === "configmaps") {
        if (JSON.stringify(orig.data) !== JSON.stringify(item.data)) {
          console.log(`[CM DIFF] ${ns}/${name}:`, { orig: orig.data, curr: item.data });
        }
      } else if (kind === "networkpolicies") {
        if (JSON.stringify(orig.spec) !== JSON.stringify(item.spec)) {
          console.log(`[NETPOL DIFF] ${ns}/${name}:`, { orig: orig.spec, curr: item.spec });
        }
      } else if (kind === "cronjobs") {
        if (JSON.stringify(orig.spec.jobTemplate.spec) !== JSON.stringify(item.spec.jobTemplate.spec)) {
          console.log(`[CRONJOB DIFF] ${ns}/${name}`);
        }
      }
    }
  }
}

checkDiff("configmaps");
checkDiff("networkpolicies");
checkDiff("cronjobs");
'

