const cj = JSON.parse(execSync(`kubectl get cronjobs -A -o json`).toString());
for (const item of cj.items) {
  const ns = item.metadata.namespace;
  const name = item.metadata.name;
  const ann = item.metadata.annotations || {};
  const lastApplied = ann["kubectl.kubernetes.io/last-applied-configuration"];
  if (lastApplied) {
    const orig = JSON.parse(lastApplied);
    console.log(`=== CRONJOB ${ns}/${name} ===`);
    console.log("ORIG containers:", JSON.stringify(orig.spec?.jobTemplate?.spec?.template?.spec?.containers));
    console.log("CURR containers:", JSON.stringify(item.spec?.jobTemplate?.spec?.template?.spec?.containers));
  }
}
'

